406 | def _run_server(repo: str, port: int):
407 |     from http.server import BaseHTTPRequestHandler, HTTPServer
408 |     import urllib.parse
409 | 
410 |     class StoryHandler(BaseHTTPRequestHandler):
411 |         def do_GET(self):
412 |             self._handle(self.path, body=None)
413 | 
414 |         def do_POST(self):
415 |             length = int(self.headers.get("Content-Length", 0))
416 |             raw = self.rfile.read(length) if length else b""
417 |             # Accept JSON body params as overrides; fall back to query string
418 |             try:
419 |                 body = json.loads(raw) if raw else {}
420 |             except Exception:
421 |                 body = {}
422 |             self._handle(self.path, body=body)
423 | 
424 |         def _handle(self, path: str, body: dict | None):
425 |             parsed = urllib.parse.urlparse(path)
426 |             if parsed.path == "/health":
427 |                 self._send_json({"status": "ok", "service": "storyteller-engine"})
428 |                 return
429 | 
430 |             qs = urllib.parse.parse_qs(parsed.query)
431 |             b = body or {}
432 | 
433 |             raw_depth = b.get("depth") or qs.get("depth", [1])[0]
434 |             depth = int(raw_depth)
435 | 
436 |             raw_layers = b.get("layers") or qs.get("layers", ["frontend,backend,db,git"])[0]
437 |             if isinstance(raw_layers, list):
438 |                 layers = [l.strip() for l in raw_layers if l.strip()]
439 |             else:
440 |                 layers = [l.strip() for l in raw_layers.split(",") if l.strip()]
441 | 
442 |             symbol = b.get("symbol") or qs.get("symbol", [None])[0]
443 | 
444 |             try:
445 |                 synth = StorySynthesizer(repo)
446 |                 res = synth.synthesize(technical_depth=depth, active_layers=layers, target_symbol=symbol)
447 |                 self._send_json(res.to_dict())
448 |             except Exception as exc:
449 |                 self._send_json({"error": str(exc)}, status=500)
450 | 
451 |         def _send_json(self, data: dict, status: int = 200):
452 |             payload = json.dumps(data).encode("utf-8")
453 |             self.send_response(status)
454 |             self.send_header("Content-Type", "application/json")
455 |             self.send_header("Access-Control-Allow-Origin", "*")
456 |             self.send_header("Content-Length", str(len(payload)))
457 |             self.end_headers()
458 |             self.wfile.write(payload)
459 | 
460 |         def log_message(self, fmt: str, *args) -> None:  # silence per-request access logs
461 |             pass
462 | 
463 |     # Probe the port before binding so Windows SO_REUSEADDR doesn't silently
464 |     # let two servers coexist on the same port.
465 |     import socket as _socket
466 |     _probe = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
467 |     _probe.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 0)
