166 |     // -----------------------------------------------------------------------
167 |     // Parse JSON output from a CLI command, with rich error reporting
168 |     // -----------------------------------------------------------------------
169 | 
170 |     private parseJsonOutput<T>(result: SpawnResult, command: string): T {
171 |         if (result.exitCode !== 0) {
172 |             const detail = result.stderr.trim() || result.stdout.trim();
173 |             throw new Error(
174 |                 `"${command}" exited with code ${result.exitCode}.\n\n${detail}`
175 |             );
176 |         }
177 | 
178 |         // The CLI may emit log lines before/after the JSON blob; extract the
179 |         // top-level JSON slice between the first and last enclosing brackets/braces.
180 |         const raw = result.stdout;
181 |         const firstBrace = raw.indexOf('{');
182 |         const firstBracket = raw.indexOf('[');
183 |         const jsonStart = firstBrace !== -1 && firstBracket !== -1
184 |             ? Math.min(firstBrace, firstBracket)
185 |             : (firstBrace !== -1 ? firstBrace : firstBracket);
186 | 
187 |         const lastBrace = raw.lastIndexOf('}');
188 |         const lastBracket = raw.lastIndexOf(']');
189 |         const jsonEnd = Math.max(lastBrace, lastBracket);
190 | 
191 |         if (jsonStart === -1 || jsonEnd === -1 || jsonEnd < jsonStart) {
192 |             throw new Error(
193 |                 `"${command}" produced no JSON output.\n\nstdout: ${raw}\nstderr: ${result.stderr}`
194 |             );
195 |         }
196 | 
197 |         const jsonSlice = raw.slice(jsonStart, jsonEnd + 1);
198 |         try {
199 |             return JSON.parse(jsonSlice) as T;
200 |         } catch (parseErr) {
201 |             throw new Error(
202 |                 `Failed to parse JSON from "${command}".\n\n` +
203 |                 `Parse error: ${String(parseErr)}\n\n` +
204 |                 `Raw output (first 1000 chars): ${jsonSlice.slice(0, 1000)}`
205 |             );
206 |         }
207 |     }
