/**
 * engineBridge.ts
 * ---------------
 * Execution bridge between the VS Code extension and the Python backend engines:
 *
 *   • tools/storyteller-engine/cli.py  – mindmap / context subcommands
 *   • orchestrator/generate_dossier.py – full ReportLab Platypus dossier
 *
 * Python interpreter resolution order
 * ------------------------------------
 *   1. storyteller.pythonPath setting (user-configured)
 *   2. <workspaceRoot>/.venv/Scripts/python.exe   (Windows venv)
 *   3. <workspaceRoot>/.venv/bin/python            (Unix venv)
 *   4. <workspaceRoot>/venv/Scripts/python.exe     (Windows venv alt)
 *   5. <workspaceRoot>/venv/bin/python             (Unix venv alt)
 *   6. "python" (Windows system) / "python3" (Unix system)
 */

import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';
import { spawn, SpawnOptionsWithoutStdio } from 'child_process';
import { ArchitectureStoryboard, AnalysisScopeOptions, DossierResult, ContextPopup, DependencyInspection } from './types';

// ---------------------------------------------------------------------------
// Internal result types
// ---------------------------------------------------------------------------

interface SpawnResult {
    stdout: string;
    stderr: string;
    exitCode: number;
}

// ---------------------------------------------------------------------------
// EngineBridge
// ---------------------------------------------------------------------------

export class EngineBridge {
    private _symbolCache = new Map<string, { popup: ContextPopup; timestamp: number }>();
    private readonly CACHE_TTL_MS = 60000;

    public get workspaceRoot(): string {
        // 1. Check open workspace folders for tools/storyteller-engine/cli.py
        const folders = vscode.workspace.workspaceFolders;
        if (folders && folders.length > 0) {
            for (const f of folders) {
                if (fs.existsSync(path.join(f.uri.fsPath, 'tools', 'storyteller-engine', 'cli.py'))) {
                    return f.uri.fsPath;
                }
            }
            return folders[0].uri.fsPath;
        }

        // 2. Check if active editor file belongs to a repo with tools/storyteller-engine
        const activeFile = vscode.window.activeTextEditor?.document?.uri?.fsPath;
        if (activeFile) {
            let cur = path.dirname(activeFile);
            while (cur && path.dirname(cur) !== cur) {
                if (fs.existsSync(path.join(cur, 'tools', 'storyteller-engine', 'cli.py'))) {
                    return cur;
                }
                cur = path.dirname(cur);
            }
        }

        // 3. Check relative to extension installation
        const relativeRoot = path.resolve(__dirname, '..', '..');
        if (fs.existsSync(path.join(relativeRoot, 'tools', 'storyteller-engine', 'cli.py'))) {
            return relativeRoot;
        }

        return folders?.[0]?.uri.fsPath ?? process.cwd();
    }

    // -----------------------------------------------------------------------
    // Python interpreter resolution
    // -----------------------------------------------------------------------

    public getPythonPath(): string {
        const configPath = vscode.workspace
            .getConfiguration('storyteller')
            .get<string>('pythonPath');

        if (configPath && configPath.trim() !== '' && fs.existsSync(configPath)) {
            return configPath;
        }

        const localAppData = process.env.LOCALAPPDATA || '';
        const candidates: string[] = [
            path.join(this.workspaceRoot, '.venv', 'Scripts', 'python.exe'),
            path.join(this.workspaceRoot, '.venv', 'bin', 'python'),
            path.join(this.workspaceRoot, 'venv', 'Scripts', 'python.exe'),
            path.join(this.workspaceRoot, 'venv', 'bin', 'python'),
        ];

        if (localAppData) {
            candidates.push(
                path.join(localAppData, 'Programs', 'Python', 'Python314', 'python.exe'),
                path.join(localAppData, 'Programs', 'Python', 'Python312', 'python.exe'),
                path.join(localAppData, 'Programs', 'Python', 'Python311', 'python.exe')
            );
        }

        for (const candidate of candidates) {
            if (fs.existsSync(candidate)) {
                return candidate;
            }
        }

        return process.platform === 'win32' ? 'python' : 'python3';
    }

    // -----------------------------------------------------------------------
    // Low-level process spawner
    // -----------------------------------------------------------------------

    private spawnProcess(
        executable: string,
        args: string[],
        cwd: string,
        token?: vscode.CancellationToken
    ): Promise<SpawnResult> {
        return new Promise((resolve, reject) => {
            const spawnOpts: SpawnOptionsWithoutStdio = {
                cwd,
                env: { ...process.env, PYTHONUNBUFFERED: '1' },
                shell: false,
            };

            const child = spawn(executable, args, spawnOpts);

            const stdoutChunks: Buffer[] = [];
            const stderrChunks: Buffer[] = [];

            child.stdout.on('data', (chunk: Buffer) => stdoutChunks.push(chunk));
            child.stderr.on('data', (chunk: Buffer) => stderrChunks.push(chunk));

            child.on('error', (err: Error) => {
                reject(
                    new Error(
                        `Failed to start process "${executable}": ${err.message}. ` +
                        `Verify storyteller.pythonPath in settings.`
                    )
                );
            });

            child.on('close', (code: number | null) => {
                resolve({
                    stdout: Buffer.concat(stdoutChunks).toString('utf8'),
                    stderr: Buffer.concat(stderrChunks).toString('utf8'),
                    exitCode: code ?? -1,
                });
            });

            // Support cancellation
            if (token) {
                token.onCancellationRequested(() => {
                    child.kill('SIGTERM');
                    reject(new vscode.CancellationError());
                });
            }
        });
    }

    // -----------------------------------------------------------------------
    // Parse JSON output from a CLI command, with rich error reporting
    // -----------------------------------------------------------------------

    private parseJsonOutput<T>(result: SpawnResult, command: string): T {
        if (result.exitCode !== 0) {
            const detail = result.stderr.trim() || result.stdout.trim();
            throw new Error(
                `"${command}" exited with code ${result.exitCode}.\n\n${detail}`
            );
        }

        // The CLI may emit log lines before/after the JSON blob; extract the
        // top-level JSON slice between the first and last enclosing brackets/braces.
        const raw = result.stdout;
        const firstBrace = raw.indexOf('{');
        const firstBracket = raw.indexOf('[');
        const jsonStart = firstBrace !== -1 && firstBracket !== -1
            ? Math.min(firstBrace, firstBracket)
            : (firstBrace !== -1 ? firstBrace : firstBracket);

        const lastBrace = raw.lastIndexOf('}');
        const lastBracket = raw.lastIndexOf(']');
        const jsonEnd = Math.max(lastBrace, lastBracket);

        if (jsonStart === -1 || jsonEnd === -1 || jsonEnd < jsonStart) {
            throw new Error(
                `"${command}" produced no JSON output.\n\nstdout: ${raw}\nstderr: ${result.stderr}`
            );
        }

        const jsonSlice = raw.slice(jsonStart, jsonEnd + 1);
        try {
            return JSON.parse(jsonSlice) as T;
        } catch (parseErr) {
            throw new Error(
                `Failed to parse JSON from "${command}".\n\n` +
                `Parse error: ${String(parseErr)}\n\n` +
                `Raw output (first 1000 chars): ${jsonSlice.slice(0, 1000)}`
            );
        }
    }

    // -----------------------------------------------------------------------
    // Validate that a required script path exists
    // -----------------------------------------------------------------------

    private assertScriptExists(scriptPath: string): void {
        if (!fs.existsSync(scriptPath)) {
            throw new Error(
                `Backend script not found: "${scriptPath}".\n` +
                `Ensure the workspace contains the tools/ and orchestrator/ directories.`
            );
        }
    }

    // -----------------------------------------------------------------------
    // Public: execute mindmap
    //
    // Invokes:
    //   python tools/storyteller-engine/cli.py mindmap
    //     --repo   <workspaceRoot>
    //     --depth  <depth>
    //     --layers <layer1,layer2,...>
    //     --json
    //     [--symbol <symbol>]
    // -----------------------------------------------------------------------

    public async executeMindmap(
        options: AnalysisScopeOptions,
        token?: vscode.CancellationToken
    ): Promise<ArchitectureStoryboard> {
        const python = this.getPythonPath();
        const cliPath = path.join(
            this.workspaceRoot,
            'tools',
            'storyteller-engine',
            'cli.py'
        );
        this.assertScriptExists(cliPath);

        const args: string[] = [
            cliPath,
            'mindmap',
            '--repo', this.workspaceRoot,
            '--depth', String(options.depth),
            '--layers', options.layers.join(','),
            '--json',
        ];

        if (options.symbol) {
            args.push('--symbol', options.symbol);
        }

        const result = await this.spawnProcess(python, args, this.workspaceRoot, token);
        return this.parseJsonOutput<ArchitectureStoryboard>(result, 'cli.py mindmap');
    }

    // -----------------------------------------------------------------------
    // Public: execute context
    //
    // Invokes:
    //   python tools/storyteller-engine/cli.py context <symbol>
    //     --repo  <workspaceRoot>
    //     --depth <depth>
    //     --json
    // -----------------------------------------------------------------------

    public async executeContext(
        options: AnalysisScopeOptions,
        token?: vscode.CancellationToken
    ): Promise<ArchitectureStoryboard> {
        if (!options.symbol) {
            throw new Error('Context analysis requires a target symbol name.');
        }

        const python = this.getPythonPath();
        const cliPath = path.join(
            this.workspaceRoot,
            'tools',
            'storyteller-engine',
            'cli.py'
        );
        this.assertScriptExists(cliPath);

        const args: string[] = [
            cliPath,
            'context',
            options.symbol,
            '--repo', this.workspaceRoot,
            '--depth', String(options.depth),
            '--json',
        ];

        if (options.layers.length > 0) {
            args.push('--layers', options.layers.join(','));
        }

        const result = await this.spawnProcess(python, args, this.workspaceRoot, token);
        return this.parseJsonOutput<ArchitectureStoryboard>(result, 'cli.py context');
    }

    // -----------------------------------------------------------------------
    // Public: execute PDF export via cli.py
    //
    // Invokes:
    //   python tools/storyteller-engine/cli.py pdf
    //     --repo       <workspaceRoot>
    //     --depth      <depth>
    //     --layers     <layer1,layer2,...>
    //     --output-dir <outputDir>
    // -----------------------------------------------------------------------

    public async executePdfExport(
        options: AnalysisScopeOptions,
        outputDir: string,
        token?: vscode.CancellationToken
    ): Promise<string> {
        const python = this.getPythonPath();
        const cliPath = path.join(
            this.workspaceRoot,
            'tools',
            'storyteller-engine',
            'cli.py'
        );
        this.assertScriptExists(cliPath);

        const args: string[] = [
            cliPath,
            'pdf',
            '--repo', this.workspaceRoot,
            '--depth', String(options.depth),
            '--layers', options.layers.join(','),
            '--output-dir', outputDir,
        ];

        const result = await this.spawnProcess(python, args, this.workspaceRoot, token);

        if (result.exitCode !== 0) {
            throw new Error(
                `cli.py pdf exited with code ${result.exitCode}.\n${result.stderr.trim()}`
            );
        }

        // cli.py pdf prints "[OK] PDF written: <path>" or "[OK] Generated Architecture Dossier HTML: <path>"
        const match = /(?:PDF written|Generated Architecture Dossier HTML)[:\s]+(.+\.(?:pdf|html))/i.exec(result.stdout);
        return match ? match[1].trim() : outputDir;
    }

    // -----------------------------------------------------------------------
    // Public: generate full dossier via orchestrator/generate_dossier.py
    //
    // Invokes:
    //   python orchestrator/generate_dossier.py
    //     --target     <workspaceRoot>
    //     --output-dir <outputDir>
    //     [--project-name <name>]
    //     [--languages <lang1 lang2 ...>]
    // -----------------------------------------------------------------------

    public async executeGenerateDossier(
        outputDir: string,
        projectName?: string,
        languages?: string[],
        token?: vscode.CancellationToken
    ): Promise<DossierResult> {
        const python = this.getPythonPath();
        const dossierScript = path.join(
            this.workspaceRoot,
            'orchestrator',
            'generate_dossier.py'
        );
        this.assertScriptExists(dossierScript);

        fs.mkdirSync(outputDir, { recursive: true });

        const args: string[] = [
            dossierScript,
            '--target', this.workspaceRoot,
            '--output-dir', outputDir,
        ];

        if (projectName) {
            args.push('--project-name', projectName);
        }

        if (languages && languages.length > 0) {
            args.push('--languages', ...languages);
        }

        const result = await this.spawnProcess(python, args, this.workspaceRoot, token);

        if (result.exitCode !== 0 && result.exitCode !== 3) {
            // Exit code 3 = PDF skipped (reportlab absent) but Markdown was written
            throw new Error(
                `generate_dossier.py exited with code ${result.exitCode}.\n${result.stderr.trim()}`
            );
        }

        // Parse key metrics from stdout lines
        const stdout = result.stdout;

        const filesMatch  = /Files scanned\s*:\s*(\d+)/i.exec(stdout);
        const symbolMatch = /Symbols extracted\s*:\s*(\d+)/i.exec(stdout);
        const engineMatch = /Engine used\s*:\s*(\S+)/i.exec(stdout);
        const pdfMatch    = /PDF written\s*:\s*(.+\.pdf)/i.exec(stdout);
        const mdMatch     = /Markdown written\s*:\s*(.+\.md)/i.exec(stdout);

        return {
            pdf_path:          pdfMatch   ? pdfMatch[1].trim()    : null,
            markdown_path:     mdMatch    ? mdMatch[1].trim()     : null,
            files_scanned:     filesMatch ? parseInt(filesMatch[1], 10) : 0,
            symbols_extracted: symbolMatch ? parseInt(symbolMatch[1], 10) : 0,
            engine:            engineMatch ? engineMatch[1].trim() : 'native',
        };
    }

    // -----------------------------------------------------------------------
    // Public: resolve output directory
    // Prefers a workspace-relative "output" folder; creates it if absent.
    // -----------------------------------------------------------------------

    public resolveOutputDir(): string {
        const outputDir = path.join(this.workspaceRoot, 'output');
        fs.mkdirSync(outputDir, { recursive: true });
        return outputDir;
    }

    // -----------------------------------------------------------------------
    // Public: resolve project name from workspace
    // -----------------------------------------------------------------------

    public resolveProjectName(): string {
        return path.basename(this.workspaceRoot);
    }

    // -----------------------------------------------------------------------
    // Public: lookupSymbol (fast cached context for code hover)
    // -----------------------------------------------------------------------

    public async lookupSymbol(
        symbolName: string,
        token?: vscode.CancellationToken
    ): Promise<ContextPopup | null> {
        const cleanName = symbolName.trim();
        if (!cleanName || cleanName.length < 2) { return null; }

        const cached = this._symbolCache.get(cleanName);
        if (cached && (Date.now() - cached.timestamp < this.CACHE_TTL_MS)) {
            return cached.popup;
        }

        try {
            const scope: AnalysisScopeOptions = {
                depth: 2,
                layers: ['git', 'backend'],
                artifact: 'context',
                symbol: cleanName,
