    // Public: inspectDependencies (inbound callers, outbound callees & risk)
    // -----------------------------------------------------------------------

    public async inspectDependencies(
        symbolName: string,
        token?: vscode.CancellationToken
    ): Promise<DependencyInspection> {
        const popup = await this.lookupSymbol(symbolName, token);

        const callers = popup?.call_sites ?? [];
        const callees = popup?.outbound_calls ?? [];
        let documentedUsage = '';

        if (popup?.definition_code) {
            const docMatch = /"""([\s\S]*?)"""|\/\*\*([\s\S]*?)\*\//.exec(popup.definition_code);
            if (docMatch) {
                documentedUsage = (docMatch[1] || docMatch[2] || '').trim().split('\n')[0].trim();
            }
        }

        if (!documentedUsage && popup?.backstory?.why_it_was_written) {
            documentedUsage = popup.backstory.why_it_was_written;
        }

        const complexity = popup?.complexity ?? 1;
        const flags = popup?.unusual_flags ?? [];
        const hasDynamic = flags.some(f => f.toLowerCase().includes('dynamic') || f.toLowerCase().includes('eval'));

        let riskLevel: 'LOW' | 'MED' | 'HIGH' = 'LOW';
        let classification = 'Cluster A (Independent Leaf - Zero Blast Radius)';

        if (hasDynamic) {
            riskLevel = 'HIGH';
            classification = 'Cluster C (Dynamic Reflection / Runtime Dispatch)';
        } else if (callers.length > 4 || complexity > 10) {
            riskLevel = 'MED';
            classification = 'Cluster B (Cross-Module Seam / High Fan-In)';
        }

        return {
            symbol_name: symbolName,
            defined_file: popup?.definition_file,
            defined_line: popup?.definition_line,
            documented_usage: documentedUsage || `Symbol '${symbolName}' with ${callers.length} cross-referenced caller(s).`,
            callers,
            callees,
            dependencies: callees,
            complexity,
            unusual_flags: flags,
            risk_level: riskLevel,
            classification,
            backstory: popup?.backstory,
        };
    }
