/**
 * extension.ts
 * ------------
 * VS Code Extension entry point for Architecture Storyteller & Archival Context.
 *
 * Registered commands
 * -------------------
 *  storyteller.mindmap       – Full storyboard + interactive Mermaid mindmap
 *  storyteller.context       – Archival context inspector for a specific symbol
 *  storyteller.pdf           – Export PDF via tools/storyteller-engine/cli.py
 *  storyteller.exportDossier – Full publication dossier via generate_dossier.py
 *
 * Lifecycle
 * ---------
 *  activate()   – called once when any activation event fires
 *  deactivate() – called on extension unload (cleanup)
 */

import * as vscode from 'vscode';
import * as path from 'path';

import { registerTerminalSlashWatcher }    from './terminalWatcher';
import { promptUserForAnalysisScope }      from './depthModal';
import { EngineBridge }                    from './engineBridge';
import {
    getOrCreatePanel,
    disposePanel,
    postMessage,
    WebviewInboundMessage,
} from './webviewPanel';
import { AnalysisScopeOptions }            from './types';
import { registerArchitectureHoverProvider } from './hoverProvider';
import { DependencyInspector }               from './dependencyInspector';

// ---------------------------------------------------------------------------
// Module-level singletons
// ---------------------------------------------------------------------------

let _bridge: EngineBridge | undefined;

function getBridge(): EngineBridge {
    if (!_bridge) {
        _bridge = new EngineBridge();
    }
    return _bridge;
}

// ---------------------------------------------------------------------------
// Shared webview message handler
// ---------------------------------------------------------------------------

let _lastStoryboard: import('./types').ArchitectureStoryboard | undefined;

function handleWebviewMessage(
    context: vscode.ExtensionContext,
    msg: WebviewInboundMessage
): void {
    switch (msg.command) {
        case 'ready':
            if (_lastStoryboard) {
                postMessage({ command: 'render', payload: _lastStoryboard });
            }
            break;

        case 'exportPdf':
            void vscode.commands.executeCommand('storyteller.pdf');
            break;

        case 'openFile': {
            if (!msg.filePath) { break; }
            const bridge = getBridge();
            const root   = (vscode.workspace.workspaceFolders?.[0]?.uri.fsPath) ?? '';
            const absPath = path.isAbsolute(msg.filePath)
                ? msg.filePath
                : path.join(root, msg.filePath);
            const fileUri = vscode.Uri.file(absPath);
            void vscode.workspace.openTextDocument(fileUri).then((doc) => {
                void vscode.window.showTextDocument(doc, {
                    preview: true,
                    selection: msg.line
                        ? new vscode.Range(
                            new vscode.Position(Math.max(0, (msg.line ?? 1) - 1), 0),
                            new vscode.Position(Math.max(0, (msg.line ?? 1) - 1), 0)
                          )
                        : undefined,
                });
            });
            break;
        }

        case 'openContext': {
            if (msg.symbolName) {
                void vscode.commands.executeCommand('storyteller.context', msg.symbolName);
            }
            break;
        }

        case 'askBobAI': {
            if (msg.symbolName) {
                void vscode.commands.executeCommand('storyteller.askBobAI', msg.symbolName);
            }
            break;
        }
    }
}

// ---------------------------------------------------------------------------
// Command: storyteller.mindmap
// ---------------------------------------------------------------------------

async function commandMindmap(
    context: vscode.ExtensionContext,
    initialSymbol?: string
): Promise<void> {
    const scope = await promptUserForAnalysisScope(initialSymbol);
    if (!scope) { return; }

    // Ensure artifact is mindmap when called from this command
    const options: AnalysisScopeOptions = { ...scope, artifact: 'mindmap' };

    const panel = getOrCreatePanel(context, (msg) => handleWebviewMessage(context, msg));
    postMessage({ command: 'loading', message: 'Analysing repository architecture…' });

    const bridge = getBridge();

    await vscode.window.withProgress(
        {
            location: vscode.ProgressLocation.Notification,
            title: 'Architecture Storyteller',
            cancellable: true,
        },
        async (_progress, token) => {
            try {
                const storyboard = await bridge.executeMindmap(options, token);
                _lastStoryboard = storyboard;
                postMessage({ command: 'render', payload: storyboard });
            } catch (err) {
                if (err instanceof vscode.CancellationError) {
                    postMessage({ command: 'error', message: 'Analysis cancelled.' });
                    return;
                }
