/**
 * extension.ts
 * ------------
 * VS Code Extension entry point for Architecture Storyteller & Archival Context.
 *
 * Registered commands
 * -------------------
 *  storyteller.mindmap       – Full storyboard + interactive Mermaid mindmap
 *  storyteller.context       – Archival context inspector for a specific symbol
 *  storyteller.pdf           – Export PDF via tools/storyteller-engine/cli.py
 *  storyteller.exportDossier – Full publication dossier via generate_dossier.py
 *
 * Lifecycle
 * ---------
 *  activate()   – called once when any activation event fires
 *  deactivate() – called on extension unload (cleanup)
 */

import * as vscode from 'vscode';
import * as path from 'path';

import { registerTerminalSlashWatcher }    from './terminalWatcher';
import { promptUserForAnalysisScope }      from './depthModal';
import { EngineBridge }                    from './engineBridge';
import {
    getOrCreatePanel,
    disposePanel,
    postMessage,
    WebviewInboundMessage,
} from './webviewPanel';
import { AnalysisScopeOptions }            from './types';
import { registerArchitectureHoverProvider } from './hoverProvider';
import { DependencyInspector }               from './dependencyInspector';

// ---------------------------------------------------------------------------
// Module-level singletons
// ---------------------------------------------------------------------------

let _bridge: EngineBridge | undefined;

function getBridge(): EngineBridge {
    if (!_bridge) {
        _bridge = new EngineBridge();
    }
    return _bridge;
}

// ---------------------------------------------------------------------------
// Shared webview message handler
// ---------------------------------------------------------------------------

let _lastStoryboard: import('./types').ArchitectureStoryboard | undefined;

function handleWebviewMessage(
    context: vscode.ExtensionContext,
    msg: WebviewInboundMessage
): void {
    switch (msg.command) {
        case 'ready':
            if (_lastStoryboard) {
                postMessage({ command: 'render', payload: _lastStoryboard });
            }
            break;

        case 'exportPdf':
            void vscode.commands.executeCommand('storyteller.pdf');
            break;

        case 'openFile': {
            if (!msg.filePath) { break; }
            const bridge = getBridge();
            const root   = (vscode.workspace.workspaceFolders?.[0]?.uri.fsPath) ?? '';
            const absPath = path.isAbsolute(msg.filePath)
                ? msg.filePath
                : path.join(root, msg.filePath);
            const fileUri = vscode.Uri.file(absPath);
            void vscode.workspace.openTextDocument(fileUri).then((doc) => {
                void vscode.window.showTextDocument(doc, {
                    preview: true,
                    selection: msg.line
                        ? new vscode.Range(
                            new vscode.Position(Math.max(0, (msg.line ?? 1) - 1), 0),
                            new vscode.Position(Math.max(0, (msg.line ?? 1) - 1), 0)
                          )
                        : undefined,
                });
            });
            break;
        }

        case 'openContext': {
            if (msg.symbolName) {
                void vscode.commands.executeCommand('storyteller.context', msg.symbolName);
            }
            break;
        }

        case 'askBobAI': {
            if (msg.symbolName) {
                void vscode.commands.executeCommand('storyteller.askBobAI', msg.symbolName);
            }
            break;
        }
    }
}

// ---------------------------------------------------------------------------
// Command: storyteller.mindmap
// ---------------------------------------------------------------------------

async function commandMindmap(
    context: vscode.ExtensionContext,
    initialSymbol?: string
): Promise<void> {
    // Open the panel first so the user sees it immediately, then show the modal
    const panel = getOrCreatePanel(context, (msg) => handleWebviewMessage(context, msg));

    const scope = await promptUserForAnalysisScope(initialSymbol);
    if (!scope) {
        // User cancelled the modal — clear the spinner so the panel isn't stuck
        postMessage({ command: 'error', message: 'Analysis cancelled. Run the command again to start.' });
        return;
    }

    // Ensure artifact is mindmap when called from this command
    const options: AnalysisScopeOptions = { ...scope, artifact: 'mindmap' };

    postMessage({ command: 'loading', message: 'Analysing repository architecture…' });

    const bridge = getBridge();

    await vscode.window.withProgress(
        {
            location: vscode.ProgressLocation.Notification,
            title: 'Architecture Storyteller',
            cancellable: true,
        },
        async (_progress, token) => {
            try {
                const storyboard = await bridge.executeMindmap(options, token);
                _lastStoryboard = storyboard;
                postMessage({ command: 'render', payload: storyboard });
            } catch (err) {
                if (err instanceof vscode.CancellationError) {
                    postMessage({ command: 'error', message: 'Analysis cancelled.' });
                    return;
                }
                const message = err instanceof Error ? err.message : String(err);
                postMessage({ command: 'error', message });
                void vscode.window.showErrorMessage(
                    `Architecture Storyteller: Mindmap failed.\n${message}`
                );
            }
        }
    );
}

// ---------------------------------------------------------------------------
// Command: storyteller.context
// ---------------------------------------------------------------------------

async function commandContext(
    context: vscode.ExtensionContext,
    symbolArg?: string
): Promise<void> {
    // Resolve initial symbol: argument > editor selection > modal input
    let initialSymbol = symbolArg;

    if (!initialSymbol) {
        const editor = vscode.window.activeTextEditor;
        if (editor) {
            const sel = editor.document.getText(editor.selection).trim();
            if (sel.length > 0 && sel.length < 120 && /^[\w.]+$/.test(sel)) {
                initialSymbol = sel;
            }
        }
    }

    const scope = await promptUserForAnalysisScope(initialSymbol);
    if (!scope) { return; }

    const options: AnalysisScopeOptions = { ...scope, artifact: 'context' };

    if (!options.symbol) {
        void vscode.window.showWarningMessage(
            'Architecture Storyteller: No symbol specified for context analysis.'
        );
        return;
    }

    const panel = getOrCreatePanel(context, (msg) => handleWebviewMessage(context, msg));
    postMessage({
        command: 'loading',
        message: `Fetching archival context for "${options.symbol}"…`,
    });

    const bridge = getBridge();

    await vscode.window.withProgress(
        {
            location: vscode.ProgressLocation.Notification,
            title: `Context: ${options.symbol}`,
            cancellable: true,
        },
        async (_progress, token) => {
            try {
                const storyboard = await bridge.executeContext(options, token);
                _lastStoryboard = storyboard;
                postMessage({ command: 'render', payload: storyboard });
            } catch (err) {
                if (err instanceof vscode.CancellationError) {
                    postMessage({ command: 'error', message: 'Context lookup cancelled.' });
                    return;
                }
                const message = err instanceof Error ? err.message : String(err);
                postMessage({ command: 'error', message });
                void vscode.window.showErrorMessage(
                    `Architecture Storyteller: Context failed.\n${message}`
                );
            }
        }
    );
}

// ---------------------------------------------------------------------------
// Command: storyteller.pdf
// ---------------------------------------------------------------------------

async function commandPdf(context: vscode.ExtensionContext): Promise<void> {
    const scope = await promptUserForAnalysisScope();
    if (!scope) { return; }

    const bridge    = getBridge();
    const outputDir = bridge.resolveOutputDir();

    await vscode.window.withProgress(
        {
            location: vscode.ProgressLocation.Notification,
            title: 'Architecture Storyteller: Exporting PDF…',
            cancellable: true,
        },
        async (_progress, token) => {
            try {
                const pdfPath = await bridge.executePdfExport(scope, outputDir, token);
                void vscode.window.showInformationMessage(
                    `Architecture Storyteller: PDF exported.`,
                    'Open Folder'
                ).then((choice) => {
                    if (choice === 'Open Folder') {
                        void vscode.commands.executeCommand(
                            'revealFileInOS',
                            vscode.Uri.file(pdfPath)
                        );
                    }
                });
            } catch (err) {
                if (err instanceof vscode.CancellationError) { return; }
                const message = err instanceof Error ? err.message : String(err);
                void vscode.window.showErrorMessage(
                    `Architecture Storyteller: PDF export failed.\n${message}`
                );
            }
        }
    );
}

// ---------------------------------------------------------------------------
// Command: storyteller.exportDossier
// ---------------------------------------------------------------------------

async function commandExportDossier(context: vscode.ExtensionContext): Promise<void> {
    const bridge      = getBridge();
    const outputDir   = bridge.resolveOutputDir();
    const projectName = bridge.resolveProjectName();

    const confirm = await vscode.window.showInformationMessage(
        `Generate a full ReportLab Platypus publication dossier for "${projectName}"?\n` +
        `Output directory: ${outputDir}`,
        { modal: true },
        'Generate'
    );

    if (confirm !== 'Generate') { return; }

    await vscode.window.withProgress(
        {
            location: vscode.ProgressLocation.Notification,
            title: `Architecture Storyteller: Generating dossier for ${projectName}…`,
            cancellable: true,
        },
        async (progress, token) => {
            try {
                progress.report({ message: 'Running AST extraction and PDF render…' });

                const result = await bridge.executeGenerateDossier(
                    outputDir,
                    projectName,
                    undefined,   // languages – analyse all
                    token
                );

                const parts: string[] = [
                    `Files scanned: ${result.files_scanned}`,
                    `Symbols: ${result.symbols_extracted}`,
                    `Engine: ${result.engine}`,
                ];

                const deliverables: string[] = [];
                if (result.pdf_path)      { deliverables.push('PDF'); }
                if (result.markdown_path) { deliverables.push('Markdown'); }

                const msg =
                    `Dossier generated (${deliverables.join(' + ')}).\n` +
                    parts.join(' • ');

                void vscode.window.showInformationMessage(msg, 'Open Output Folder')
                    .then((choice) => {
                        if (choice === 'Open Output Folder') {
                            void vscode.commands.executeCommand(
                                'revealFileInOS',
                                vscode.Uri.file(result.pdf_path ?? result.markdown_path ?? outputDir)
                            );
                        }
                    });

            } catch (err) {
                if (err instanceof vscode.CancellationError) { return; }
                const message = err instanceof Error ? err.message : String(err);
                void vscode.window.showErrorMessage(
                    `Architecture Storyteller: Dossier generation failed.\n${message}`
                );
            }
        }
    );
}

// ---------------------------------------------------------------------------
// Command: storyteller.askBobAI
// ---------------------------------------------------------------------------

async function commandAskBobAI(
    context: vscode.ExtensionContext,
    symbolArg?: string
): Promise<void> {
    let symbol = symbolArg;
    if (!symbol) {
        const editor = vscode.window.activeTextEditor;
        if (editor) {
            const sel = editor.document.getText(editor.selection).trim();
            if (sel) {
                symbol = sel;
            } else {
                const range = editor.document.getWordRangeAtPosition(editor.selection.active);
                if (range) {
                    symbol = editor.document.getText(range).trim();
                }
            }
        }
    }

    const defaultPrompt = symbol
        ? `Analyze architectural role, cross-module blast radius, and refactoring safety for '${symbol}'`
        : `Explain overall codebase architecture, risk hotspots, and blast radius`;

    const userPrompt = await vscode.window.showInputBox({
        prompt: `Ask IBM Bob AI about ${symbol ? `component "${symbol}"` : 'codebase architecture'}`,
        value: defaultPrompt,
        placeHolder: 'e.g., How can I safely refactor this without breaking callers?',
    });

    if (!userPrompt) { return; }

    try {
        await vscode.commands.executeCommand('workbench.action.chat.open', {
            query: `@bob ${userPrompt}`,
        });
    } catch {
        const bridge = getBridge();
        const bridgeScript = path.join(bridge.workspaceRoot, 'scripts', 'bob_bridge.py');
        const terminal = vscode.window.createTerminal('IBM Bob AI Dispatch');
        terminal.show();
        terminal.sendText(`python "${bridgeScript}" --agent --prompt "${userPrompt.replace(/"/g, '\\"')}"`);
    }
}

// ---------------------------------------------------------------------------
// Activation / Deactivation
// ---------------------------------------------------------------------------

export function activate(context: vscode.ExtensionContext): void {
    // Create the bridge eagerly so python path is resolved on activation
    _bridge = new EngineBridge();

    // Register terminal slash-command watcher
    registerTerminalSlashWatcher(context);

    // Register Architecture Hover Provider (short documented usage on hover)
    registerArchitectureHoverProvider(context, getBridge());

    // Dependency Inspector instance
    const dependencyInspector = new DependencyInspector(getBridge());

    // Register commands
    context.subscriptions.push(
        vscode.commands.registerCommand(
            'storyteller.mindmap',
            (symbolArg?: string) => commandMindmap(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.context',
            (symbolArg?: string) => commandContext(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.inspectDependencies',
            (symbolArg?: string) => dependencyInspector.inspect(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.askBobAI',
            (symbolArg?: string) => commandAskBobAI(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.pdf',
            () => commandPdf(context)
        ),

        vscode.commands.registerCommand(
            'storyteller.exportDossier',
            () => commandExportDossier(context)
        )
    );

    // Status-bar item for quick access
    const statusBar = vscode.window.createStatusBarItem(
        vscode.StatusBarAlignment.Right,
        100
    );
    statusBar.command = 'storyteller.mindmap';
    statusBar.text    = '$(type-hierarchy-sub) Storyteller';
    statusBar.tooltip = 'Open Architecture Storyboard & Mindmap';
    statusBar.show();
    context.subscriptions.push(statusBar);
}

export function deactivate(): void {
    disposePanel();
    _bridge = undefined;
}

