                if (err instanceof vscode.CancellationError) { return; }
                const message = err instanceof Error ? err.message : String(err);
                void vscode.window.showErrorMessage(
                    `Architecture Storyteller: Dossier generation failed.\n${message}`
                );
            }
        }
    );
}

// ---------------------------------------------------------------------------
// Command: storyteller.askBobAI
// ---------------------------------------------------------------------------

async function commandAskBobAI(
    context: vscode.ExtensionContext,
    symbolArg?: string
): Promise<void> {
    let symbol = symbolArg;
    if (!symbol) {
        const editor = vscode.window.activeTextEditor;
        if (editor) {
            const sel = editor.document.getText(editor.selection).trim();
            if (sel) {
                symbol = sel;
            } else {
                const range = editor.document.getWordRangeAtPosition(editor.selection.active);
                if (range) {
                    symbol = editor.document.getText(range).trim();
                }
            }
        }
    }

    const defaultPrompt = symbol
        ? `Analyze architectural role, cross-module blast radius, and refactoring safety for '${symbol}'`
        : `Explain overall codebase architecture, risk hotspots, and blast radius`;

    const userPrompt = await vscode.window.showInputBox({
        prompt: `Ask IBM Bob AI about ${symbol ? `component "${symbol}"` : 'codebase architecture'}`,
        value: defaultPrompt,
        placeHolder: 'e.g., How can I safely refactor this without breaking callers?',
    });

    if (!userPrompt) { return; }

    try {
        await vscode.commands.executeCommand('workbench.action.chat.open', {
            query: `@bob ${userPrompt}`,
        });
    } catch {
        const bridge = getBridge();
        const bridgeScript = path.join(bridge.workspaceRoot, 'scripts', 'bob_bridge.py');
        const terminal = vscode.window.createTerminal('IBM Bob AI Dispatch');
        terminal.show();
        terminal.sendText(`python "${bridgeScript}" --agent --prompt "${userPrompt.replace(/"/g, '\\"')}"`);
    }
}

// ---------------------------------------------------------------------------
// Activation / Deactivation
// ---------------------------------------------------------------------------

export function activate(context: vscode.ExtensionContext): void {
    // Create the bridge eagerly so python path is resolved on activation
    _bridge = new EngineBridge();

    // Register terminal slash-command watcher
    registerTerminalSlashWatcher(context);

    // Register Architecture Hover Provider (short documented usage on hover)
    registerArchitectureHoverProvider(context, getBridge());

    // Dependency Inspector instance
    const dependencyInspector = new DependencyInspector(getBridge());

    // Register commands
    context.subscriptions.push(
        vscode.commands.registerCommand(
            'storyteller.mindmap',
            (symbolArg?: string) => commandMindmap(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.context',
            (symbolArg?: string) => commandContext(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.inspectDependencies',
            (symbolArg?: string) => dependencyInspector.inspect(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.askBobAI',
            (symbolArg?: string) => commandAskBobAI(context, symbolArg)
        ),

        vscode.commands.registerCommand(
            'storyteller.pdf',
            () => commandPdf(context)
        ),

        vscode.commands.registerCommand(
            'storyteller.exportDossier',
            () => commandExportDossier(context)
        )
    );

    // Status-bar item for quick access
    const statusBar = vscode.window.createStatusBarItem(
        vscode.StatusBarAlignment.Right,
        100
    );
    statusBar.command = 'storyteller.mindmap';
    statusBar.text    = '$(type-hierarchy-sub) Storyteller';
    statusBar.tooltip = 'Open Architecture Storyboard & Mindmap';
    statusBar.show();
    context.subscriptions.push(statusBar);
}

export function deactivate(): void {
    disposePanel();
    _bridge = undefined;
}

